-- Full Cyber Essentials question bank (87 questions, CE v3.2 "Willow" question set, SA overlay)
-- Source: docs/extracted/CE-SA-App/CyberEssentialsSA.html (CONTROLS array).
-- Pure content — attaches to the EXISTING global cyber_essentials content pack v1
-- (created by 20260812000001_cyber_essentials_pack.sql); zero schema change, zero code change.
--
-- Column mapping from the prototype:
--   control.ceRef + question id  -> regulatory_ref  ('<ceRef> · Q <id>')
--   question id                  -> uid             ('ce.<id>', e.g. 'ce.A4.3')
--   guidance / options / placeholder / saContext (per question) and saNote (per control,
--   the South-Africa overlay)    -> why_matters     (labelled blocks, in that order)
--   req ('core'|'std')           -> risk            (core -> 'High', std -> 'Low')
--   type (yesno/notes/select/multi/options) has no column in the engine — the fixed
--   fully_compliant/partial/non_compliant/na response scale applies; original answer
--   options are preserved inside why_matters.
--
-- Sections reuse the seed's section_id/section_name so the screens group them together:
--   0 Organisation & Scope (new) · 1 Firewalls · 2 Secure Configuration
--   3 Security Update Management · 4 User Access Control · 5 Malware Protection
-- question_number continues after the seed rows (1,2) in each existing section.
--
-- 9 prototype questions are NOT inserted because the 20260812000001 seed already covers
-- their substance (matched by question text; seed uid on the right):
--   A4.1   ≈ ce.fw1
--   A4.2   ≈ ce.fw2
--   A5.1   ≈ ce.sc1
--   A6.1   ≈ ce.up1
--   A6.4   ≈ ce.up2
--   A7.1   ≈ ce.ac1
--   A7.16  ≈ ce.ac2
--   A8.2   ≈ ce.mw1
--   A8.4   ≈ ce.mw2
-- ce.sc2 (documented secure-configuration standard) has no prototype counterpart and
-- simply remains alongside the bank. 87 - 9 = 78 rows inserted below.

BEGIN;

INSERT INTO public.assessment_questions
  (framework, content_pack_id, section_id, section_name, question_number, question, why_matters, regulatory_ref, risk, uid)
SELECT 'cyber_essentials', cp.id, x.section_id, x.section_name, x.qn, x.question, x.why, x.ref, x.risk, x.uid
FROM (SELECT id FROM public.content_packs
      WHERE framework_key='cyber_essentials' AND version=1 AND practice_id IS NULL) cp,
(VALUES
  (0,'Organisation & Scope',1,'What is your organisation''s name?',E'Provide the legal trading name of your organisation.\n\nExample answer — e.g. Acme (Pty) Ltd\n\nSA context: For SA: Use the full registered name as it appears with the CIPC (Companies and Intellectual Property Commission).\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A1.1','Low','ce.A1.1'),
  (0,'Organisation & Scope',2,'What type of organisation are you?',E'Select the legal structure that best describes your organisation.\n\nAnswer options: (Pty) Ltd – Private Company | CC – Close Corporation | NPO – Non-Profit Organisation | Public Entity / SOE | Sole Proprietor / Partnership | Other\n\nSA context: SA organisation types include (Pty) Ltd, CC (Close Corporation), NPO, Public Entity, or Sole Proprietor.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A1.2','Low','ce.A1.2'),
  (0,'Organisation & Scope',3,'What is your organisation''s registration number?',E'Provide your official registration number as issued by CIPC or relevant authority.\n\nSA context: SA companies: CIPC registration number. NPOs: NPO registration number from DSD. CCs: CC registration number.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A1.3','Low','ce.A1.3'),
  (0,'Organisation & Scope',4,'What is your organisation''s physical address?',E'Include all office locations that fall within scope of this assessment.\n\nSA context: Provide your registered business address in South Africa including province and postal code.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A1.4','Low','ce.A1.4'),
  (0,'Organisation & Scope',5,'What is your main business activity?',E'Select the primary industry sector of your organisation.\n\nAnswer options: Financial Services / Fintech | Healthcare / Medical | Retail / E-commerce | Professional Services / Consulting | Manufacturing / Engineering | ICT / Technology | Education / Training | Government / Public Sector | Construction / Property | Agriculture / Mining | Non-Profit / NGO | Other\n\nSA context: South African industry classifications follow the SIC codes used by Stats SA. Select the category that best matches your CIPC primary business activity.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A1.5','Low','ce.A1.5'),
  (0,'Organisation & Scope',6,'What is your website address (if applicable)?',E'Provide your website address. A social media page is acceptable if no website exists.\n\nExample answer — e.g. https://www.yourcompany.co.za\n\nSA context: Include your primary .co.za or .org.za domain. If you use multiple domains, list all that are in scope.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A1.6','Low','ce.A1.6'),
  (0,'Organisation & Scope',7,'Is this a first-time application or a renewal of an existing certification?',E'Select whether this is your first CE assessment or a renewal.\n\nAnswer options: First Time Application | Renewal of Existing Certification\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A1.7','Low','ce.A1.7'),
  (0,'Organisation & Scope',8,'What are your primary reasons for applying for Cyber Essentials certification?',E'Select up to two primary reasons. SA regulators include the FSCA (financial sector), HPCSA (health), and various sector-specific bodies.\n\nAnswer options: Required for a commercial contract | Required for a government / public sector contract | Required by our insurer | Required by a regulator (e.g. FSCA, HPCSA) | To give confidence to our customers / clients | To improve our overall security posture | Required for a grant or funding | Required for supply-chain / tender compliance | Other\n\nSA context: South African regulatory drivers: FSCA GUIDANCE NOTE 3 of 2021 (cybersecurity for FSPs), SARB Prudential Standard CPS 234, NHI Act cybersecurity requirements, SITA requirements for government suppliers.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A1.8','Low','ce.A1.8'),
  (0,'Organisation & Scope',9,'Have you read the Cyber Essentials Requirements for IT Infrastructure v3.2 document (April 2025)?',E'This document is mandatory reading. It defines all technical requirements for certification. Available at ncsc.gov.uk/cyberessentials.\n\nSA context: The CE framework is the international baseline. Combined with POPIA Section 19 (security safeguards) and the Cybercrimes Act, this forms your complete SA cybersecurity compliance baseline.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A1.9','High','ce.A1.9'),
  (0,'Organisation & Scope',10,'Can the certification body contact you if you experience a cyber breach, to assist with incident analysis?',E'This helps improve the overall effectiveness of the certification scheme.\n\nSA context: Under the Cybercrimes Act (Act 19 of 2020), cybercrime incidents must be reported to the South African Police Service (SAPS). Under POPIA, security breaches involving personal information must be reported to the Information Regulator and affected data subjects.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A1.10','Low','ce.A1.10'),
  (0,'Organisation & Scope',11,'Does the scope of this assessment cover your whole organisation?',E'Whole organisation includes all networks, people and devices which access your organisational data and services. If yes, this is the recommended approach.\n\nSA context: For POPIA compliance, whole-organisation scope is strongly recommended — POPIA Section 19 applies to all processing of personal information regardless of system or department.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A2.1','High','ce.A2.1'),
  (0,'Organisation & Scope',12,'If not whole organisation, provide your scope description (including clear exclusion statements).',E'Maximum 300 characters for certificate. Must include clear exclusion statements. Any network with internet access that is excluded must be clearly documented.\n\nExample answer — e.g. Whole organisation excluding the development test network at Cape Town office.\n\nSA context: Any excluded scope must still comply with POPIA requirements independently.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A2.2','Low','ce.A2.2'),
  (0,'Organisation & Scope',13,'Please describe the geographical locations of your business in scope.',E'List all business locations included in this assessment.\n\nExample answer — e.g. Head office Johannesburg (Gauteng), Branch Cape Town (Western Cape), Remote workers nationally.\n\nSA context: For cross-border data transfers (e.g. to servers outside SA), POPIA Section 72 requires adequate data protection in the receiving country. List any international locations.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A2.3','Low','ce.A2.3'),
  (0,'Organisation & Scope',14,'List the quantities and operating systems for all laptops, desktops and virtual desktops in scope. Include make and OS version.',E'Include BYOD devices that access organisational data. Windows 10 users must be enrolled in Microsoft ESU (Extended Security Updates) post October 2025.\n\nExample answer — e.g. 15x Dell laptops running Windows 11 Pro 23H2; 5x Apple MacBook running macOS Sonoma 14.4; 3x HP desktops running Windows 10 Pro 22H2 (ESU enrolled).\n\nSA context: Common SA deployment: Microsoft 365 (M365) or Google Workspace. Confirm all devices are running supported OS versions. Unlicensed software violates both CE requirements and SA copyright law.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A2.4','High','ce.A2.4'),
  (0,'Organisation & Scope',15,'List servers, virtual servers and hypervisors in scope. Include OS version.',E'Include on-premise and cloud-hosted servers. Include hypervisors.\n\nExample answer — e.g. 2x VMware ESXi 8.0 hosting 6x Windows Server 2022; 1x Ubuntu 22.04 LTS web server; Microsoft Azure (IaaS).\n\nSA context: SA common cloud providers: Microsoft Azure, AWS (Cape Town region), Google Cloud, or local providers (Liquid Intelligent Technologies, MTN BusinessConnect, Vodacom Cloud). Include all.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A2.5','High','ce.A2.5'),
  (0,'Organisation & Scope',16,'List tablets and mobile devices in scope. Include make and OS version.',E'Include all BYOD mobile devices used to access organisational data or cloud services.\n\nExample answer — e.g. 20x Samsung Galaxy running Android 14; 10x Apple iPad running iPadOS 17.4; 8x iPhone running iOS 17.4.\n\nSA context: For BYOD devices: POPIA requires that personal information accessed on personal devices remains protected. Consider an MDM (Mobile Device Management) solution — popular SA options include Microsoft Intune or Jamf.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A2.6','High','ce.A2.6'),
  (0,'Organisation & Scope',17,'List all networks in scope (name, location, purpose).',E'Include name, location and purpose of each network. Do not include IP addresses.\n\nExample answer — e.g. Main LAN – Johannesburg HQ – general business use; Guest WiFi – Cape Town branch – visitor internet only; Azure VNet – cloud services.\n\nSA context: Common SA network providers: Fibre (Vumatel, OpenServe, Frogfoot), Fixed LTE (MTN, Vodacom, Telkom), Satellite (Starlink now available in SA). Include all connection types.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A2.7','High','ce.A2.7'),
  (0,'Organisation & Scope',18,'How many staff are home workers or remote workers?',E'Any employee permitted to work remotely at time of assessment must be counted as a remote worker. CE v3.2 expanded this to include all remote/mobile working, not just home working.\n\nExample answer — e.g. 12 full-time remote workers using VPN; 5 hybrid workers (3 days office / 2 days remote).\n\nSA context: Post-2020, remote working is widespread in SA. Remote workers using home or mobile internet connections must have software firewalls enabled on their devices. Consider load-shedding contingencies — remote workers on generator/UPS should still meet CE controls.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A2.7.1','High','ce.A2.7.1'),
  (0,'Organisation & Scope',19,'List all network equipment in scope: firewalls, routers. Include make AND model.',E'Include make and model for all firewall and routing devices. Note: CE v3.2 requires both make AND model for network devices (unlike end-user devices).\n\nExample answer — e.g. Fortinet FortiGate 60F (boundary firewall); Mikrotik hEX RB750Gr3 (office router); Cisco Meraki MX64 (remote site); Draytek Vigor 2866 (ADSL backup).\n\nSA context: Popular SA network equipment: Fortinet, Draytek, Mikrotik, Cisco Meraki, Sophos. Ensure all firmware is current — vendors release updates regularly to address SA-specific threat intelligence.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A2.8','High','ce.A2.8'),
  (0,'Organisation & Scope',20,'List all cloud services used by your organisation.',E'Cloud services cannot be excluded from CE scope. Include all IaaS, PaaS and SaaS. Include any third-party hosted applications.\n\nExample answer — e.g. Microsoft 365 (SaaS – email, Office apps); Azure AD / Entra ID (SaaS – identity); AWS S3 (IaaS – file storage); Xero (SaaS – accounting); Salesforce (SaaS – CRM); Pastel/Sage (SaaS – accounting).\n\nSA context: Common SA cloud services: Microsoft 365, Google Workspace, Xero, Sage/Pastel, PaySpace/Payroll, VIP Payroll, DocuSign, Zoom, Teams. All must be included in scope.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A2.9','High','ce.A2.9'),
  (0,'Organisation & Scope',21,'Provide name and role of the person responsible for managing your IT systems in scope.',E'Must be a member of your organisation. Cannot be exclusively your outsourced IT provider.\n\nExample answer — e.g. John Smith, IT Manager (internal). Or: Jane Doe, Director – ICT Outsourced to TechCo MSP.\n\nSA context: Under POPIA, an Information Officer must be designated and registered with the Information Regulator (www.justice.gov.za/inforeg). This person often also oversees IT security.\n\nSA note (Organisation & Scope): SA businesses must also consider their obligations under POPIA (Act 4 of 2013) and the Cybercrimes Act (Act 19 of 2020) when defining scope.','Organisation — Your Organisation & Scope of Assessment · Q A2.10','High','ce.A2.10'),
  (1,'Firewalls',3,'Do you have software firewalls enabled on ALL computers, laptops and servers?',E'CE Requirement: Software firewalls must be enabled even when behind a hardware firewall. This is especially critical for remote/mobile workers on untrusted networks.\n\nSA context: Windows Defender Firewall (built-in), macOS Firewall (built-in), UFW/iptables for Linux. All must be enabled. Remote workers at coffee shops, airports or using Telkom/Vodacom hotspots are at elevated risk — software firewalls are the last line of defence.\n\nSA note (Firewalls): Firewall requirements align with POPIA Section 19 (security safeguards) and SABS ISO/IEC 27001 Annex A.13 (network security).','CE Technical Control 1 — Boundary Firewalls and Internet Gateways · Q A4.1.1','High','ce.A4.1.1'),
  (1,'Firewalls',4,'If no software firewalls: is this only because the OS does not include one by default? List those operating systems.',E'Only very few OS do not include software firewalls. Windows, macOS and common Linux distributions all have built-in firewalls.\n\nExample answer — e.g. Embedded Linux on control systems (isolated from internet); custom IoT OS on CCTV server.\n\nSA note (Firewalls): Firewall requirements align with POPIA Section 19 (security safeguards) and SABS ISO/IEC 27001 Annex A.13 (network security).','CE Technical Control 1 — Boundary Firewalls and Internet Gateways · Q A4.1.2','Low','ce.A4.1.2'),
  (1,'Firewalls',5,'Describe your process for changing firewall passwords (including for home routers supplied by your organisation).',E'Describe how you manage firewall password changes. Include who does it, how, and where passwords are stored.\n\nExample answer — e.g. On deployment, IT team logs into admin portal and changes password to unique 16+ character passphrase stored in Bitwarden. Documented in asset register.\n\nSA context: Password managers recommended for SA businesses: Bitwarden (free tier available), 1Password, LastPass. Avoid sticky notes or shared spreadsheets for password storage.\n\nSA note (Firewalls): Firewall requirements align with POPIA Section 19 (security safeguards) and SABS ISO/IEC 27001 Annex A.13 (network security).','CE Technical Control 1 — Boundary Firewalls and Internet Gateways · Q A4.2.1','High','ce.A4.2.1'),
  (1,'Firewalls',6,E'Which method is used to configure your firewall administrative passwords?\n\nA. Multi-factor authentication (MFA) with minimum 8-character password\nB. Automatic blocking of common passwords with minimum 8-character password\nC. Minimum 12-character password with no maximum length\nD. Passwordless authentication (CE v3.2 new) — describe\nE. None of the above — describe',E'CE v3.2 (2025): Passwordless authentication is now formally accepted. Options D and E require detailed notes.\n\nAnswer options: A. MFA + minimum 8-character password | B. Auto-block common passwords + minimum 8 characters | C. Minimum 12-character password (no maximum) | D. Passwordless authentication (biometric/passkey) — add detail in notes | E. None of the above — describe in notes\n\nSA context: MFA option (A) is strongly recommended for SA businesses — the FSCA and SARB both recommend MFA as a baseline control. Microsoft Authenticator, Google Authenticator, and Duo are free/low-cost options widely used in SA.\n\nSA note (Firewalls): Firewall requirements align with POPIA Section 19 (security safeguards) and SABS ISO/IEC 27001 Annex A.13 (network security).','CE Technical Control 1 — Boundary Firewalls and Internet Gateways · Q A4.3','High','ce.A4.3'),
  (1,'Firewalls',7,'If Option D or E selected above: provide details of your authentication method.',E'Required if Option D (passwordless) or E (none) is selected.\n\nExample answer — e.g. D: Hardware YubiKey tokens used for all firewall admin access. / E: Explain why none of the above applies and compensating controls used.\n\nSA note (Firewalls): Firewall requirements align with POPIA Section 19 (security safeguards) and SABS ISO/IEC 27001 Annex A.13 (network security).','CE Technical Control 1 — Boundary Firewalls and Internet Gateways · Q A4.3.notes','Low','ce.A4.3.notes'),
  (1,'Firewalls',8,'Do you change firewall passwords promptly when you know or suspect a compromise?',E'CE Requirement: Establish a process to change passwords promptly when a password or account is known or suspected to be compromised.\n\nSA context: Under POPIA Section 22, a security compromise involving personal information must be reported to the Information Regulator and affected parties. A firewall breach likely constitutes such a compromise. Document your incident response process.\n\nSA note (Firewalls): Firewall requirements align with POPIA Section 19 (security safeguards) and SABS ISO/IEC 27001 Annex A.13 (network security).','CE Technical Control 1 — Boundary Firewalls and Internet Gateways · Q A4.4','High','ce.A4.4'),
  (1,'Firewalls',9,'Do you have a formal process to manage changes to your firewall rules?',E'Any decision to allow external internet traffic into your network (opening a port) must have a documented business justification.\n\nSA context: Firewall rule changes should be tracked in a change log. For regulated SA businesses (FSPs, healthcare), this change log is often a regulatory audit requirement.\n\nSA note (Firewalls): Firewall requirements align with POPIA Section 19 (security safeguards) and SABS ISO/IEC 27001 Annex A.13 (network security).','CE Technical Control 1 — Boundary Firewalls and Internet Gateways · Q A4.5','High','ce.A4.5'),
  (1,'Firewalls',10,'Have you reviewed your firewall rules in the last 12 months? Describe the review process.',E'CE Requirement: Remove or disable inbound firewall rules quickly when they are no longer needed. You must have a documented review process.\n\nExample answer — e.g. Annual firewall audit conducted by IT Manager in January each year. Rules reviewed against business requirements, unused ports closed. Documented in firewall policy v2.1.\n\nSA context: Annual review minimum. For businesses processing financial data or health records, quarterly review recommended per FSCA and HPCSA guidance.\n\nSA note (Firewalls): Firewall requirements align with POPIA Section 19 (security safeguards) and SABS ISO/IEC 27001 Annex A.13 (network security).','CE Technical Control 1 — Boundary Firewalls and Internet Gateways · Q A4.6','High','ce.A4.6'),
  (1,'Firewalls',11,'Is your firewall configured to BLOCK unauthenticated inbound connections by default?',E'CE Requirement: Block unauthenticated inbound connections by default. Most correctly configured firewalls do this. Answer Yes if your default posture is to deny inbound.\n\nSA context: A "deny all inbound" default policy is the correct answer here. If your ISP-supplied router is the only firewall and it uses NAT only, verify it blocks unsolicited inbound connections.\n\nSA note (Firewalls): Firewall requirements align with POPIA Section 19 (security safeguards) and SABS ISO/IEC 27001 Annex A.13 (network security).','CE Technical Control 1 — Boundary Firewalls and Internet Gateways · Q A4.7','High','ce.A4.7'),
  (1,'Firewalls',12,'Describe how you approve and document any permitted inbound connections.',E'CE Requirement: Inbound firewall rules must be approved by an authorised person and include documented business justification. Board-level sign-off required.\n\nExample answer — e.g. Any inbound rule requires written approval from the Director (signed form). Business justification documented in our firewall change log. Reviewed quarterly.\n\nSA context: For SA businesses: document using email approval chain or a change management form. For ISO 27001 alignment (increasingly required by large SA corporates and government), formal change management is mandatory.\n\nSA note (Firewalls): Firewall requirements align with POPIA Section 19 (security safeguards) and SABS ISO/IEC 27001 Annex A.13 (network security).','CE Technical Control 1 — Boundary Firewalls and Internet Gateways · Q A4.8','High','ce.A4.8'),
  (1,'Firewalls',13,'Are your boundary firewalls configured to allow internet access to their configuration/admin settings?',E'Answer Yes if your firewall admin portal is accessible directly from the internet (not via VPN). Answer No if admin access is only possible from inside the network or via VPN.\n\nSA context: Remote admin of firewalls over the open internet is a high-risk configuration. SA MSPs (Managed Service Providers) often configure this for convenience — ensure it is protected by MFA and IP allowlisting if used.\n\nSA note (Firewalls): Firewall requirements align with POPIA Section 19 (security safeguards) and SABS ISO/IEC 27001 Annex A.13 (network security).','CE Technical Control 1 — Boundary Firewalls and Internet Gateways · Q A4.9','High','ce.A4.9'),
  (1,'Firewalls',14,'If yes to A4.9: Is there a documented business requirement for internet-accessible firewall administration?',E'CE Requirement: If remote admin access is permitted, it must be documented with a clear business justification approved at board level.\n\nSA context: If your IT support company requires remote admin access, document this in a written agreement. Ensure this access is MFA-protected — POPIA requires appropriate safeguards for any access to systems holding personal information.\n\nSA note (Firewalls): Firewall requirements align with POPIA Section 19 (security safeguards) and SABS ISO/IEC 27001 Annex A.13 (network security).','CE Technical Control 1 — Boundary Firewalls and Internet Gateways · Q A4.10','High','ce.A4.10'),
  (1,'Firewalls',15,'If yes to A4.9: Is remote firewall admin access protected by MFA, or restricted to a trusted IP allowlist with managed authentication?',E'CE Requirement: Remote admin interface must be protected by MFA OR an IP allowlist combined with managed authentication.\n\nExample answer — e.g. Remote admin only permitted via VPN with MFA (Cisco AnyConnect + Microsoft Authenticator). Admin panel blocked from internet directly.\n\nSA context: For SA MSPs: IP allowlisting alone (using your MSP office IP) is acceptable only when combined with strong password management. MFA is the gold standard.\n\nSA note (Firewalls): Firewall requirements align with POPIA Section 19 (security safeguards) and SABS ISO/IEC 27001 Annex A.13 (network security).','CE Technical Control 1 — Boundary Firewalls and Internet Gateways · Q A4.11','High','ce.A4.11'),
  (2,'Secure Configuration',3,'Do all in-scope devices and cloud services only contain necessary, actively-used user accounts?',E'CE Requirement: Regularly remove and disable unnecessary user accounts including guest accounts and unused administrative accounts.\n\nSA context: Pay particular attention to: ex-employee accounts (critical when staff leave), generic "admin" accounts, supplier or contractor accounts. For M365, use the Azure AD/Entra ID access reviews feature. For SA payroll staff, ensure accounts are disabled same-day on termination — POPIA requires this.\n\nSA note (Secure Configuration): Secure configuration aligns with POPIA Section 19 (technical safeguards) and ISO/IEC 27001 Annex A.12 (operations security).','CE Technical Control 2 — Secure Configuration · Q A5.2','High','ce.A5.2'),
  (2,'Secure Configuration',4,'Have you changed all default passwords for user and administrator accounts on all in-scope devices?',E'CE Requirement: Regularly change any default or guessable account passwords. Use technical controls to manage password quality (MFA, 12+ character minimum, or auto-blocking of common passwords).\n\nSA context: Default credentials are the #1 attack vector in SA SME breaches per SABRIC (South African Banking Risk Information Centre) annual reports. Change all defaults immediately on provisioning any new device or service.\n\nSA note (Secure Configuration): Secure configuration aligns with POPIA Section 19 (technical safeguards) and ISO/IEC 27001 Annex A.12 (operations security).','CE Technical Control 2 — Secure Configuration · Q A5.3','High','ce.A5.3'),
  (2,'Secure Configuration',5,'Do you run or host external services that provide internet-accessible access to organisational data? (e.g. VPN, web portal, hosted app, mail server)',E'CE Requirement: Ensure users are authenticated before allowing access to organisational data or services. This includes any internet-facing application.\n\nSA context: Common SA examples: Hosted accounting systems (Pastel/Sage Online), payroll portals (PaySpace, SARS eFiling integration), remote desktop / VPN, customer-facing web applications. All must require authentication.\n\nSA note (Secure Configuration): Secure configuration aligns with POPIA Section 19 (technical safeguards) and ISO/IEC 27001 Annex A.12 (operations security).','CE Technical Control 2 — Secure Configuration · Q A5.4','High','ce.A5.4'),
  (2,'Secure Configuration',6,E'For external services (if A5.4 Yes): which authentication method is used?\n\nA. MFA + minimum 8-character password\nB. Auto-block common passwords + minimum 8-character password\nC. Minimum 12-character password (no maximum)\nD. Passwordless (CE v3.2 new) — describe\nE. None of the above — describe',E'CE v3.2 (2025): Passwordless authentication formally accepted. Options D and E require detailed description.\n\nAnswer options: A. MFA + minimum 8-character password | B. Auto-block common passwords + minimum 8 characters | C. Minimum 12-character password (no maximum length) | D. Passwordless authentication (passkey/biometric) — add detail below | E. None of the above — describe below\n\nSA context: FSCA GUIDANCE NOTE 3 of 2021 requires MFA for all internet-facing systems for SA financial services providers. Option A (MFA) is strongly recommended across all SA regulated sectors.\n\nSA note (Secure Configuration): Secure configuration aligns with POPIA Section 19 (technical safeguards) and ISO/IEC 27001 Annex A.12 (operations security).','CE Technical Control 2 — Secure Configuration · Q A5.5','High','ce.A5.5'),
  (2,'Secure Configuration',7,'If D or E selected above: describe your authentication approach.',E'Example answer — e.g. D: FIDO2 passkeys implemented on customer portal via Azure Entra. / E: Legacy system — describe compensating controls.\n\nSA note (Secure Configuration): Secure configuration aligns with POPIA Section 19 (technical safeguards) and ISO/IEC 27001 Annex A.12 (operations security).','CE Technical Control 2 — Secure Configuration · Q A5.5.notes','Low','ce.A5.5.notes'),
  (2,'Secure Configuration',8,'Describe your process for changing passwords on external services when you suspect a compromise.',E'CE Requirement: Have an established process to change passwords promptly when an account is suspected to be compromised.\n\nExample answer — e.g. IT Manager alerted via monitoring alert or staff report. Password reset within 1 hour. Account locked pending investigation. All sessions terminated. Incident logged.\n\nSA context: Under POPIA Section 22: if the compromise involves personal information, notify the Information Regulator (inforeg@justice.gov.za) and affected data subjects as soon as reasonably possible. Under the Cybercrimes Act: report cybercrime to SAPS (www.saps.gov.za/cybercrime).\n\nSA note (Secure Configuration): Secure configuration aligns with POPIA Section 19 (technical safeguards) and ISO/IEC 27001 Annex A.12 (operations security).','CE Technical Control 2 — Secure Configuration · Q A5.6','High','ce.A5.6'),
  (2,'Secure Configuration',9,E'When not using MFA, which brute-force protection is used for external services?\n\nA. Rate throttling (max 10 attempts per 5 minutes)\nB. Account lockout after 10 failed attempts\nC. None of the above — describe',E'CE Requirement: Protect authentication against brute-force attacks using throttling or lockout. When vendor does not allow configuration, use vendor default.\n\nAnswer options: A. Rate throttling (max 10 guesses in 5 minutes) | B. Account lockout after 10 failed attempts | C. None of the above — describe below\n\nSA context: If using a cloud service (e.g. M365, Google Workspace, Xero) that enforces its own brute-force protection, this is acceptable. Document the vendor''s policy.\n\nSA note (Secure Configuration): Secure configuration aligns with POPIA Section 19 (technical safeguards) and ISO/IEC 27001 Annex A.12 (operations security).','CE Technical Control 2 — Secure Configuration · Q A5.7','High','ce.A5.7'),
  (2,'Secure Configuration',10,'Have you disabled auto-run / auto-execute features that run files automatically when downloaded or inserted (e.g. USB auto-play)?',E'CE Requirement: Disable any auto-run feature that allows file execution without user authorisation.\n\nSA context: USB auto-run is a common malware vector in SA offices. Disable via Group Policy on Windows (Computer Config > Admin Templates > Windows Components > AutoPlay Policies). For home users, Windows 11 has this disabled by default.\n\nSA note (Secure Configuration): Secure configuration aligns with POPIA Section 19 (technical safeguards) and ISO/IEC 27001 Annex A.12 (operations security).','CE Technical Control 2 — Secure Configuration · Q A5.8','High','ce.A5.8'),
  (2,'Secure Configuration',11,'Do you enforce a locking mechanism (password, PIN, or biometric) on all devices that require physical presence to access?',E'CE Requirement: Ensure appropriate device locking controls for users physically present. CE v3.2: PIN must be minimum 6 characters if used as device lock only.\n\nSA context: Screen lock is especially important in SA open-plan offices and for laptops used at client sites. Recommended: 5-minute auto-lock timeout. For mobile devices, enforce via MDM policy.\n\nSA note (Secure Configuration): Secure configuration aligns with POPIA Section 19 (technical safeguards) and ISO/IEC 27001 Annex A.12 (operations security).','CE Technical Control 2 — Secure Configuration · Q A5.9','High','ce.A5.9'),
  (2,'Secure Configuration',12,'Which methods do you use to unlock devices? Describe for each device type.',E'CE v3.2: Device unlock credentials (PIN min 6 chars, password, or biometric). Must be protected against brute-force. Use throttling or lockout after 10 failed attempts.\n\nExample answer — e.g. Laptops: Windows Hello PIN (8 digits) or fingerprint. Mobile phones: 6-digit PIN or biometric (Face ID / fingerprint). Servers: Complex password (16+ chars). Tablets: 6-digit PIN.\n\nSA context: For SA businesses with field workers (mining, agriculture, construction), biometric unlock is preferred as workers may wear gloves. Consider remote wipe capability via MDM for lost/stolen devices — critical for POPIA compliance.\n\nSA note (Secure Configuration): Secure configuration aligns with POPIA Section 19 (technical safeguards) and ISO/IEC 27001 Annex A.12 (operations security).','CE Technical Control 2 — Secure Configuration · Q A5.10','High','ce.A5.10'),
  (3,'Security Update Management',3,'Is ALL software on in-scope devices supported by a supplier providing regular security updates?',E'CE Requirement: All software must be licensed and supported. Includes all applications, extensions, scripts and libraries.\n\nSA context: Check for SA-specific software that may not receive regular updates: older versions of Pastel/Sage, VIP Payroll versions below v7, or local line-of-business applications. Contact the vendor to confirm update policy.\n\nSA note (Security Updates): Patch management within 14 days aligns with POPIA Section 19 and is recommended by SABS ISO/IEC 27002:2022 Section 8.8.','CE Technical Control 3 — Security Update Management · Q A6.2','High','ce.A6.2'),
  (3,'Security Update Management',4,'List all internet browsers used, including version numbers.',E'List all browsers across all in-scope devices. Version required. Must be current supported versions.\n\nExample answer — e.g. Google Chrome 124.0 (auto-update enabled); Microsoft Edge 124.0 (auto-update enabled); Safari 17.4 on macOS.\n\nSA context: Recommend disabling old browser versions. Internet Explorer is end-of-life — if still used (common in SA legacy systems), this must be addressed. Chrome and Edge auto-update by default.\n\nSA note (Security Updates): Patch management within 14 days aligns with POPIA Section 19 and is recommended by SABS ISO/IEC 27002:2022 Section 8.8.','CE Technical Control 3 — Security Update Management · Q A6.2.1','High','ce.A6.2.1'),
  (3,'Security Update Management',5,'List all anti-malware / endpoint protection software and version numbers.',E'List all malware protection software. Version required. Must be current.\n\nExample answer — e.g. Microsoft Defender (built-in, auto-updated, Windows 11); Sophos Intercept X v2.0.20 (auto-update enabled); Malwarebytes Premium v5.1.\n\nSA context: Cost-effective SA options: Microsoft Defender (free, built into Windows — adequate for CE), Sophos Home, ESET NOD32. For SMEs, avoid expired or perpetual-licence AV software — it will not be receiving updates.\n\nSA note (Security Updates): Patch management within 14 days aligns with POPIA Section 19 and is recommended by SABS ISO/IEC 27002:2022 Section 8.8.','CE Technical Control 3 — Security Update Management · Q A6.2.2','High','ce.A6.2.2'),
  (3,'Security Update Management',6,'List all email applications on end-user devices and servers, including version numbers.',E'List all email clients. Version required.\n\nExample answer — e.g. Microsoft Outlook (M365 Apps, auto-updated); Gmail via browser (no local client); Apple Mail on macOS Sonoma (auto-updated).\n\nSA context: Common SA email platforms: Microsoft 365 (Outlook), Google Workspace (Gmail), or on-premise Exchange. Ensure Exchange Server is current — Exchange 2013 and 2016 are end-of-life. Consider migrating to M365 if still on legacy Exchange.\n\nSA note (Security Updates): Patch management within 14 days aligns with POPIA Section 19 and is recommended by SABS ISO/IEC 27002:2022 Section 8.8.','CE Technical Control 3 — Security Update Management · Q A6.2.3','High','ce.A6.2.3'),
  (3,'Security Update Management',7,'List all office/productivity applications used to create organisational data, including version numbers.',E'List all office applications. Version required.\n\nExample answer — e.g. Microsoft 365 Apps v2404 (auto-update via M365 admin centre); Google Workspace (browser-based, always current); LibreOffice 24.2 (auto-update enabled).\n\nSA context: Common SA options: Microsoft 365 (most common), Google Workspace, Sage/Pastel. Perpetual licences (Office 2016, Office 2019) are approaching or past end-of-support. Migrate to Microsoft 365 subscription for automatic updates.\n\nSA note (Security Updates): Patch management within 14 days aligns with POPIA Section 19 and is recommended by SABS ISO/IEC 27002:2022 Section 8.8.','CE Technical Control 3 — Security Update Management · Q A6.2.4','High','ce.A6.2.4'),
  (3,'Security Update Management',8,'Are any in-scope software or cloud services unlicensed or unsupported?',E'CE Requirement: All software must be licensed and supported. Answer No if all is licensed and supported (this is the desired answer).\n\nSA context: Pirated software is common in SA SMEs — this is a CE certification failure AND a violation of the Copyright Act (Act 98 of 1978). It also creates severe security risks as pirated software often contains malware. Audit and remediate before certification.\n\nSA note (Security Updates): Patch management within 14 days aligns with POPIA Section 19 and is recommended by SABS ISO/IEC 27002:2022 Section 8.8.','CE Technical Control 3 — Security Update Management · Q A6.3','High','ce.A6.3'),
  (3,'Security Update Management',9,'If yes to A6.3: list all unlicensed or unsupported software.',E'List all unlicensed or unsupported software and your remediation plan.\n\nExample answer — e.g. Old version of Pastel v14 (end-of-support) — migrating to Sage Business Cloud in Q3. No licence for Adobe Acrobat — replacing with PDF24 (free).\n\nSA note (Security Updates): Patch management within 14 days aligns with POPIA Section 19 and is recommended by SABS ISO/IEC 27002:2022 Section 8.8.','CE Technical Control 3 — Security Update Management · Q A6.3.1','Low','ce.A6.3.1'),
  (3,'Security Update Management',10,'Are OS updates applied via auto-update on all devices where possible?',E'CE Requirement: Auto-updates must be enabled where possible. For any device where auto-updates cannot be enabled, a manual process must be documented.\n\nSA context: Enable Windows Update automatic installation. For M365 devices, use Microsoft Endpoint Manager / Intune to enforce update policies. For Android devices, enable auto-update in Google Play settings.\n\nSA note (Security Updates): Patch management within 14 days aligns with POPIA Section 19 and is recommended by SABS ISO/IEC 27002:2022 Section 8.8.','CE Technical Control 3 — Security Update Management · Q A6.4.1','High','ce.A6.4.1'),
  (3,'Security Update Management',11,'Where auto-updates are NOT used: describe how you ensure critical OS and firmware updates are applied within 14 days.',E'If only auto-updates are used, confirm this here. Otherwise describe your manual update management process.\n\nExample answer — e.g. Servers: WSUS (Windows Server Update Services) managed by IT Manager, weekly check and approval. Firewall firmware: IT Manager subscribes to Fortinet security alerts, applies patches within 7 days. Documented in change log.\n\nSA context: For SA MSPs managing client devices: use RMM (Remote Monitoring and Management) tools (e.g. NinjaRMM, ConnectWise, N-central) to automate patching. Document your SLA for patching timescales.\n\nSA note (Security Updates): Patch management within 14 days aligns with POPIA Section 19 and is recommended by SABS ISO/IEC 27002:2022 Section 8.8.','CE Technical Control 3 — Security Update Management · Q A6.4.2','High','ce.A6.4.2'),
  (3,'Security Update Management',12,'Are ALL high-risk/critical application security updates installed within 14 days of release?',E'CE Requirement: Application updates with CVSSv3 ≥ 7.0 or vendor-rated "critical/high" must be applied within 14 days.\n\nSA context: This includes browser extensions, plugins, PDF readers, and line-of-business applications. Ensure your software inventory is complete so no applications are missed during patching cycles.\n\nSA note (Security Updates): Patch management within 14 days aligns with POPIA Section 19 and is recommended by SABS ISO/IEC 27002:2022 Section 8.8.','CE Technical Control 3 — Security Update Management · Q A6.5','High','ce.A6.5'),
  (3,'Security Update Management',13,'Are application updates applied via auto-update on all devices where possible?',E'CE Requirement: Auto-updates must be enabled for applications where possible.\n\nSA context: Enable auto-update in: Chrome, Edge (browser settings), M365 Apps (M365 admin centre), Adobe Reader (Help > Check for updates), Zoom (auto-update in settings).\n\nSA note (Security Updates): Patch management within 14 days aligns with POPIA Section 19 and is recommended by SABS ISO/IEC 27002:2022 Section 8.8.','CE Technical Control 3 — Security Update Management · Q A6.5.1','High','ce.A6.5.1'),
  (3,'Security Update Management',14,'Where app auto-updates are NOT used: describe how you ensure critical updates are applied within 14 days.',E'Describe your manual process if auto-update is not used. Confirm update frequency and who is responsible.\n\nExample answer — e.g. Bespoke CRM application: vendor sends security alerts by email. IT Manager applies updates within 5 working days and documents in change log. Verified by Director quarterly.\n\nSA note (Security Updates): Patch management within 14 days aligns with POPIA Section 19 and is recommended by SABS ISO/IEC 27002:2022 Section 8.8.','CE Technical Control 3 — Security Update Management · Q A6.5.2','High','ce.A6.5.2'),
  (3,'Security Update Management',15,'Have you removed all software that is no longer supported and receives no further security updates?',E'CE Requirement: Remove unsupported software from devices, or place devices in an air-gapped sub-set with no internet access.\n\nSA context: Unsupported software found in SA: Internet Explorer, Office 2010/2013, Windows XP/7 (found in POS, ATM, industrial control systems). Must be removed from scope or isolated before CE certification is possible.\n\nSA note (Security Updates): Patch management within 14 days aligns with POPIA Section 19 and is recommended by SABS ISO/IEC 27002:2022 Section 8.8.','CE Technical Control 3 — Security Update Management · Q A6.6','High','ce.A6.6'),
  (3,'Security Update Management',16,'Where unsupported software must be retained (business-critical): have you moved those devices out of scope by isolating them from the internet? Explain.',E'CE Requirement: Unsupported software must be on an isolated sub-set (firewall or VLAN separation) with no internet traffic. This prevents whole-organisation certification.\n\nExample answer — e.g. Legacy CNC machine controller running Windows XP — isolated on dedicated VLAN with no internet access, no access to other networks. Excluded from CE scope with clear statement in A2.2.\n\nSA context: Common in SA manufacturing/industrial sector: legacy SCADA/ICS systems running old Windows. Isolate on dedicated OT (Operational Technology) network with hardware firewall separation.\n\nSA note (Security Updates): Patch management within 14 days aligns with POPIA Section 19 and is recommended by SABS ISO/IEC 27002:2022 Section 8.8.','CE Technical Control 3 — Security Update Management · Q A6.7','High','ce.A6.7'),
  (4,'User Access Control',3,'Are ALL user and administrative accounts accessed using unique credentials (not shared)?',E'CE Requirement: Authenticate users with unique credentials. No shared accounts. No generic logins.\n\nSA context: Shared accounts are a significant POPIA risk — if a breach occurs, you cannot identify which individual accessed data. Ensure even small SA businesses assign unique credentials per person, including external IT support staff.\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.2','High','ce.A7.2'),
  (4,'User Access Control',4,'Describe how you ensure accounts are deleted or disabled when staff leave your organisation.',E'CE Requirement: Remove or disable user accounts when no longer required. Prompt revocation is essential.\n\nExample answer — e.g. HR notifies IT Manager on day of departure. IT Manager disables AD account, revokes M365 licence, removes from all groups and cloud services within same day. Leaver checklist signed off by HR and IT.\n\nSA context: POPIA requires limiting access to personal information to authorised personnel only. Failure to revoke access for leavers is a common POPIA breach scenario. Same-day revocation is the recommended SA practice. Include in your HR offboarding process.\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.3','High','ce.A7.3'),
  (4,'User Access Control',5,'Do staff only have the access privileges needed for their current job role? How do you enforce this?',E'CE Requirement: Apply principle of least privilege. Control user accounts and access to organisational data and services.\n\nExample answer — e.g. Principle of least privilege applied. Standard users have no admin rights. Finance team has read-only access to HR data. Access rights reviewed when roles change. Documented in access matrix spreadsheet.\n\nSA context: For SA POPIA compliance: maintain a data access register showing which roles can access which categories of personal information. This is required under POPIA''s accountability principle (Section 8).\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.4','High','ce.A7.4'),
  (4,'User Access Control',6,'Do you have a formal process for granting administrator-level access? Describe it.',E'CE Requirement: Have a documented process to create and approve elevated privilege accounts.\n\nExample answer — e.g. Admin access request submitted in writing to Director. Business justification required. Director approval documented. Admin account created separately from standard account. Quarterly review of all admin accounts.\n\nSA context: For SA regulated businesses: admin account provisioning should be logged and auditable. FSCA and SARB cybersecurity guidance requires segregation of duties for privileged access in financial services.\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.5','High','ce.A7.5'),
  (4,'User Access Control',7,'How do you ensure separate accounts are used for administrative tasks (installing software, config changes) vs. everyday tasks?',E'CE Requirement: Use separate accounts for administrative activities only. No emailing, web browsing, or other standard activities should be performed with admin accounts.\n\nExample answer — e.g. All IT staff have two accounts: standard user account (email, web browsing, office work) and a separate admin account (used only for system admin tasks). Admin accounts not linked to email.\n\nSA context: This is critical: using admin accounts for email opens the entire organisation to credential theft and malware. Common SA MSP guidance is to use the standard account for 99% of work and elevate only when necessary (Windows UAC prompt is acceptable).\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.6','High','ce.A7.6'),
  (4,'User Access Control',8,'How does your organisation prevent administrator accounts from being used for everyday activities like email or web browsing?',E'CE Requirement: Administrative accounts must be used for admin activities only.\n\nExample answer — e.g. Admin accounts have no mailbox configured. Web browsing disabled by policy on admin accounts via Group Policy. Staff trained to use only standard accounts for daily work. Monitored via SIEM alerts.\n\nSA context: Technical control options: no email licence assigned to admin accounts, Group Policy blocking browser access, privileged access workstations (PAWs). Policy + training is acceptable for smaller SA businesses.\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.7','High','ce.A7.7'),
  (4,'User Access Control',9,'Do you formally track all users with administrator accounts in your organisation?',E'CE Requirement: Maintain a tracked list of all users with administrative privileges.\n\nSA context: Maintain a privileged user register — a simple spreadsheet listing name, role, systems they have admin access to, and date granted. Review regularly. This register is valuable evidence during a POPIA compliance audit.\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.8','High','ce.A7.8'),
  (4,'User Access Control',10,'Do you regularly review who should have administrative access, removing it when no longer needed?',E'CE Requirement: Regularly remove or disable special access privileges when no longer required.\n\nSA context: Review frequency: monthly or quarterly recommended for SA SMEs. Include in your IT governance calendar. Annual review is the minimum acceptable. Role changes (promotions, department moves) should trigger an immediate access review.\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.9','High','ce.A7.9'),
  (4,'User Access Control',11,'How are your password-based systems protected from brute-force attacks?',E'CE Requirement: Protect passwords against brute-force using MFA, throttling (max 10 guesses in 5 minutes), or lockout after max 10 attempts.\n\nExample answer — e.g. Windows accounts: locked after 10 failed attempts (Group Policy). M365: Smart lockout + MFA enabled for all users. VPN: Locked after 5 failed attempts. Documented in security policy.\n\nSA context: Microsoft 365 includes Smart Lockout by default. Enable Entra ID Identity Protection for enhanced brute-force detection. For on-premise AD: configure Account Lockout Policy via Group Policy.\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.10','High','ce.A7.10'),
  (4,'User Access Control',12,'Which technical controls manage password quality across your organisation?',E'CE Requirement: Use one of: MFA, minimum 12-char passwords (no max), or minimum 8-char with auto-blocking of common passwords.\n\nExample answer — e.g. M365: minimum 8-char password + MFA required (Conditional Access policy). Windows domain: minimum 12-char, complexity disabled (three random words approach). Password manager (Bitwarden) encouraged for all staff.\n\nSA context: CE v3.2 aligns with NCSC guidance: avoid password complexity rules and forced expiry (they make passwords weaker, not stronger). Use the "three random words" method. Password managers are strongly encouraged.\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.11','High','ce.A7.11'),
  (4,'User Access Control',13,'How do you encourage staff to use unique and strong passwords for work accounts?',E'CE Requirement: Support users to choose unique passwords. Promote password managers, three-random-words approach, avoid forced expiry and complexity rules.\n\nExample answer — e.g. Annual security awareness training includes password hygiene session. Bitwarden password manager provided to all staff (Teams-integrated). Three random words method communicated in new starter pack. Password sharing between work and personal accounts prohibited by policy.\n\nSA context: Recommended SA approach: provide a free password manager (Bitwarden free tier), include in onboarding, brief at annual security awareness session. Phishing simulation training (e.g. KnowBe4, GoPhish) reinforces good password habits.\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.12','High','ce.A7.12'),
  (4,'User Access Control',14,'Do you have a documented process for when passwords or accounts are suspected to be compromised?',E'CE Requirement: Establish a process to change passwords promptly when compromise is known or suspected.\n\nSA context: Your compromise response process should include: immediate password reset, session termination, incident log, notification to the Information Regulator if personal data was exposed (POPIA Section 22), and SAPS report if criminal activity suspected (Cybercrimes Act).\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.13','High','ce.A7.13'),
  (4,'User Access Control',15,'Do all your cloud services offer multi-factor authentication (MFA) as part of the service?',E'CE Requirement: MFA must be implemented for all cloud services where available. If a cloud service does not support MFA, it must be listed.\n\nSA context: If your cloud service does not offer MFA, consider replacing it. FSCA requires MFA for all internet-facing financial services systems. Most SA-used cloud services (M365, Google Workspace, Xero, Sage Cloud) support MFA.\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.14','High','ce.A7.14'),
  (4,'User Access Control',16,'If No to A7.14: list all cloud services that do NOT offer any MFA option.',E'List any cloud services where MFA is genuinely unavailable. This is informational — it does not automatically cause certification failure if compensating controls exist.\n\nExample answer — e.g. Legacy ERP system v4.2 (vendor end-of-life, no MFA support) — migrating to cloud ERP in H2. Legacy payroll portal (MFA not available — raising with vendor).\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.15','Low','ce.A7.15'),
  (4,'User Access Control',17,'Has MFA been applied to ALL standard users on all cloud services?',E'CE Requirement: All users of cloud services must use MFA.\n\nSA context: Enable MFA for all M365/Google Workspace users. Use Conditional Access policies (M365) or Context-Aware Access (Google) to enforce MFA. In SA, mobile-based MFA apps (Microsoft Authenticator, Google Authenticator) are widely accessible at no cost.\n\nSA note (User Access Control): Access control requirements align directly with POPIA Section 19 (safeguards for personal information) and SABS ISO/IEC 27001 Annex A.9.','CE Technical Control 4 — User Access Control & Administrative Accounts · Q A7.17','High','ce.A7.17'),
  (5,'Malware Protection',3,E'How are all desktops, laptops, tablets and mobile phones protected from malware?\n\nA. Anti-malware software installed\nB. Application allowlisting (app store / MDM / code signing)\nC. None of the above — describe',E'CE Requirement: At least one malware protection method must be active on all in-scope devices. Most organisations will need both A and B (A for Windows/Mac, B for mobiles/tablets).\n\nAnswer options: A. Anti-malware software installed on all applicable devices | B. Application allowlisting (approved app store / MDM / code signing) | C. None of the above — describe in notes below\n\nSA context: For SA Windows devices: Microsoft Defender (free, built into Windows 10/11) is CE-compliant. For Android: Google Play Protect (built-in). For iOS/iPadOS: App Store restriction (no sideloading) is sufficient for Option B. Budget options: Sophos Home Free, Malwarebytes Free (detection only — not real-time).\n\nSA note (Malware Protection): Malware protection is required under POPIA Section 19 and aligns with SABS ISO/IEC 27002:2022 Section 8.7 (protection against malware).','CE Technical Control 5 — Malware Protection · Q A8.1','High','ce.A8.1'),
  (5,'Malware Protection',4,'If Option C (none of the above): explain your approach.',E'Example answer — e.g. Only if C selected: describe your compensating controls for malware prevention.\n\nSA note (Malware Protection): Malware protection is required under POPIA Section 19 and aligns with SABS ISO/IEC 27002:2022 Section 8.7 (protection against malware).','CE Technical Control 5 — Malware Protection · Q A8.1.notes','Low','ce.A8.1.notes'),
  (5,'Malware Protection',5,'(If Option A selected): Is anti-malware set to scan web pages and warn about malicious websites?',E'CE Requirement: Anti-malware must prevent connections to malicious websites over the internet.\n\nSA context: Windows Defender SmartScreen provides this on Windows 11 and in Microsoft Edge. For Chrome: use Google Safe Browsing (enabled by default). Dedicated DNS filtering (e.g. Cisco Umbrella, Cloudflare Gateway — free tier available) provides additional web protection, recommended for SA businesses.\n\nSA note (Malware Protection): Malware protection is required under POPIA Section 19 and aligns with SABS ISO/IEC 27002:2022 Section 8.7 (protection against malware).','CE Technical Control 5 — Malware Protection · Q A8.3','High','ce.A8.3'),
  (5,'Malware Protection',6,'(If Option B selected): Do you maintain and enforce a list of approved applications, ensuring users can only install these?',E'CE Requirement: Actively approve applications before deploying. Maintain a current list. Users must not be able to install unsigned or invalid-signature applications.\n\nSA context: MDM solutions for SA SMEs: Microsoft Intune (included in M365 Business Premium), Jamf (Apple devices), or Google Endpoint Management (Google Workspace). Maintaining an approved app list in Intune or a simple spreadsheet is acceptable for smaller SA businesses.\n\nSA note (Malware Protection): Malware protection is required under POPIA Section 19 and aligns with SABS ISO/IEC 27002:2022 Section 8.7 (protection against malware).','CE Technical Control 5 — Malware Protection · Q A8.5','High','ce.A8.5'),
  (5,'Malware Protection',7,'Additional notes on your malware protection approach, tools used, or any exceptions.',E'Optional: provide additional context about your malware protection strategy.\n\nExample answer — e.g. Microsoft Defender for Business deployed across all Windows 11 devices via Intune. Google Play Protect active on all Android devices. iOS App Store restriction enforced. DNS filtering via Cloudflare Gateway. Monthly security scan report reviewed by IT Manager.\n\nSA context: Ransomware is the most significant malware threat in SA per SABRIC (South African Banking Risk Information Centre). Ensure backups are maintained offline and tested regularly (3-2-1 backup rule). Offline backups are your last line of defence against ransomware.\n\nSA note (Malware Protection): Malware protection is required under POPIA Section 19 and aligns with SABS ISO/IEC 27002:2022 Section 8.7 (protection against malware).','CE Technical Control 5 — Malware Protection · Q A8.6','Low','ce.A8.6')
) AS x(section_id,section_name,qn,question,why,ref,risk,uid)
ON CONFLICT (uid) DO NOTHING;

COMMIT;
